  [6887] = { { "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間Spell Damageが$N4上昇します。さらに、敵を倒して得られる経験値が$N6%増加します。", "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間Spell Damageが$N4上昇します。", shape = { "6/3", "5/3" } }, 0xcbfd0593, "u" },
  [6888] = { { "$D1かけて体力を$N1回復。回復中は座っている必要があります。10秒以上食事に時間をかけると満腹状態になり、$D3の間スタミナを$N4上昇させます。さらに、敵を倒して得られる経験値が$N6%増加します。", "$D1かけて体力を$N1回復。回復中は座っている必要があります。10秒以上食事に時間をかけると満腹状態になり、$D3の間スタミナを$N4上昇させます。", shape = { "6/3", "5/3" } }, 0x07c351a2, "u" },
  [6890] = { { "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間筋力が$N4上昇します。さらに、敵を倒して得られる経験値が$N6%増加します。", "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間筋力が$N4上昇します。", shape = { "6/3", "5/3" } }, 0x6052ea7e, "u" },
  [6892] = { "Smoked Bear Meatの調理法を習得する。", 0xd5338bf9, "u" },
  [6897] = { "Berserker Stance（Rank $N1）を習得します。Intercept（Rank $N2）を習得します。", 0x0d8c8664, "u" },
  [6898] = { "$D2の間、$N2秒ごとに体力を$N1回復します。", 0xe8cdadbe, "u" },
  [6904] = { "対象に毒を与え、$D2の間、$D1ごとに$N1のNatureダメージを与えます。", 0xc6bab046, "u" },
  [6907] = { "受けるSpell Damageが$N1減少します。", 0x1d9ea266, "u" },
  [6909] = { "$N1のFireダメージと$N2のFrostダメージを与え、$D1の間対象を$N3%スローにし、アーマーを$N5減少させ、$D3の間$D2ごとに$N6のNatureダメージを与えます。", 0xb94bba7a, "u" },
  [6913] = { "召喚円を使ってsuccubusを呼び出します。", 0x39bf5bb5, "u" },
  [6926] = { "この手紙は密封されている。", 0x2923d554, "u" },
  [6928] = { "召喚円を使ってvoidwalkerを呼び出します。", 0x9c46052b, "u" },
  [6929] = { "右クリックで読める。", 0x28fd7623, "u" },
  [6931] = { "召喚円を使ってfelhunterを呼び出します。\n鍵のかかった本の表紙には、かすれた文字で「Tome of the Cabal」と書かれています。", 0x697a04fc, "u" },
  [6947] = { "武器に毒を塗ります。毒は$N1分間持続します。\n攻撃が命中するたびに$N2%の確率で敵を毒に侵し、即座に$N3のNatureダメージを与えます。チャージ数は$N4回です。", 0x87fac2e2, "u" },
  [6948] = { "ホームに設定した場所へ戻ります。別の場所のInnkeeperに話しかけると、ホームの場所を変更できます。", 0xf92eb2a9, "u" },
  [6949] = { "武器に毒を塗ります。毒は$N1分間持続します。\n攻撃が命中するたびに$N2%の確率で敵を毒に侵し、即座に$N3のNatureダメージを与えます。チャージ数は$N4回です。", 0xf235d067, "u" },
  [6950] = { "武器に毒を塗ります。毒は$N1分間持続します。\n攻撃が命中するたびに$N2%の確率で敵を毒に侵し、即座に$N3のNatureダメージを与えます。チャージ数は$N4回です。", 0x7a650e6f, "u" },
  [6951] = { "武器に$N1分間持続する毒を塗ります。\n攻撃が命中するたびに$N2%の確率で敵を毒に冒し、$D1の間、詠唱時間を$N3%延ばします。$N5回分。", 0xda8ce359, "u" },
  [6953] = { "対象をGreat Forgeの炎で焼き、$N1のHolyfireダメージを与えます。Fire ElementalsとEarth Elementalsには$N2倍のダメージを与えます。", 0x1fe0e4bc, "u" },
  [6972] = { "怒りを$N1増加させます。", 0x7d85c197, "u" },
  [6988] = { "Summon Felhunterを習得します。", 0x294f2d58, "u" },
